package com.pm.agile.controller;

import com.pm.agile.entity.ProjectBoard;
import com.pm.agile.repository.ProjectBoardRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/boards")
public class ProjectBoardController {

    private final ProjectBoardRepository boardRepository;

    public ProjectBoardController(ProjectBoardRepository boardRepository) {
        this.boardRepository = boardRepository;
    }

    @GetMapping("/{boardId}")
    public ResponseEntity<ProjectBoard> getBoard(@PathVariable Long boardId) {
        // Direct entity serialization traverses @OneToMany billingCodes
        ProjectBoard board = boardRepository.findById(boardId)
                .orElseThrow(() -> new IllegalArgumentException("Board not found"));
        return ResponseEntity.ok(board);
    }
}

